/* ---------- Invariants I-1…I-12 ---------- */

export const INVARIANTS = [
  { id: "I-1", t: "The data plane cannot mutate control-plane state except through an authorised command", enforced: "T2 containers have no DB role, no network except the egress proxy and gateway passthrough; the worker (host) is the only bridge.", proof: "INV-1 + A3.1" },
  { id: "I-2", t: "No agent can widen its own scope, autonomy level, or credential set", enforced: "Grants and autonomy live in the applied definition (read-only to agents); factory.write is never granted; credential minting is broker-only.", proof: "INV-2, AT-5, AT-8" },
  { id: "I-3", t: "Every consequential action is attributable to an authority and is in the event log", enforced: "Broker step 10 + the state-machine transition both append events in the same DB transaction.", proof: "INV-3, A3.12" },
  { id: "I-4", t: "No merge occurs without a passing acceptance oracle and the applicable approval", enforced: "Required check factory/merge-gate bound to the head SHA + branch ruleset + CODEOWNERS.", proof: "INV-4, A1.7" },
  { id: "I-5", t: "No factory change takes effect without a reviewed, evaluated, reversible change", enforced: "The applier only reads a merged git SHA; control-surface writes are rejected.", proof: "INV-5, A0.7, AT-6/7" },
  { id: "I-6", t: "Untrusted content cannot become instruction", enforced: "Tag-at-ingest, envelope-last, proposed actions re-checked by policy; no tool or grant derives from content.", proof: "INV-6, AT-1/2/3" },
  { id: "I-7", t: "No production write occurs outside an enumerated runbook", enforced: "v1 has NO production capability at all — a test asserts none is registered.", proof: "INV-7" },
  { id: "I-8", t: "Every run's context is pinned and recoverable", enforced: "context_envelopes row + object; resolvedContextSha256 on every run.", proof: "INV-8, A0.4" },
  { id: "I-9", t: "No dependency on a single model provider for correctness or governance", enforced: "Gateway adapters; fake + second provider; a failover test.", proof: "INV-9" },
  { id: "I-10", t: "No agent-authored test alone satisfies an acceptance criterion", enforced: "Authorship flags in the GateReport; oracle admission rejects implementationRunId != null.", proof: "INV-10, A1.6" },
  { id: "I-11", t: "Surplus capacity is allocated by policy, not by default", enforced: "Scheduler concurrency + per-workflow caps from the definition; no auto-fill.", proof: "INV-11" },
  { id: "I-12", t: "Every component is replaceable without changing the definition, workflows, or agent contracts", enforced: "All components behind packages/contracts interfaces; each has an in-memory fake used in tests.", proof: "INV-12" },
];

/* ---------- Red-team attacks AT-1…AT-15 ---------- */

export const ATTACKS = [
  { id: "AT-1", name: "Prompt injection via issue body", kind: "injection", desc: "An issue body carries an embedded instruction that the agent follows.", defence: "Untrusted content tagged at ingest, fenced and placed last in the envelope. The agent can only propose; policy re-checks every action." },
  { id: "AT-2", name: "Prompt injection via fetched URL", kind: "injection", desc: "A web page or dependency README contains instructions aimed at the agent.", defence: "The control-plane fetch service caps size/time and blocks SSRF; fetched content is untrusted-content class." },
  { id: "AT-3", name: "Prompt injection via CI log", kind: "injection", desc: "A CI log line tries to redirect the D-2 repair agent.", defence: "CI logs are read via github.ci.read, which declares result trust untrusted." },
  { id: "AT-4", name: "Scope escalation", kind: "escalation", desc: "An agent attempts to write outside its granted path scope.", defence: "Three-scope rule: workflow ∩ stage ∩ resource. The narrowest wins; deny always wins." },
  { id: "AT-5", name: "Self-granted authority", kind: "escalation", desc: "An agent tries to raise its own autonomy level or mint a credential.", defence: "Grants live in the read-only applied definition; factory.write is never granted; the broker is the only minter." },
  { id: "AT-6", name: "Definition write via a tool path", kind: "escalation", desc: "An agent reaches the definition through an unexpected tool.", defence: "deny-factory-write; the applier role is the only writer of definition_versions; protected paths." },
  { id: "AT-7", name: "Definition write via a direct path", kind: "escalation", desc: "A capability adapter writes the definition without the applier.", defence: "The applier is the ONLY role with INSERT on definition_versions. Every other role is REVOKEd." },
  { id: "AT-8", name: "Credential leakage into context", kind: "exfiltration", desc: "A minted credential ends up in a prompt, an argument, or a stored artefact.", defence: "Credential broker injects at the invocation boundary only; redaction at capture; the leak check scans every stored artefact." },
  { id: "AT-9", name: "Egress to a disallowed host", kind: "exfiltration", desc: "A T2 container tries to reach the internet directly.", defence: "Default-deny egress proxy. Only allow-listed hosts, port 443. Private/loopback/metadata ranges refused after DNS resolution. The proxy down means no network." },
  { id: "AT-10", name: "SSRF via the proxy", kind: "exfiltration", desc: "An allow-listed name resolves to a private IP.", defence: "DNS is resolved IN the proxy; the resolved address is checked against private ranges." },
  { id: "AT-11", name: "Container escape attempt", kind: "containment", desc: "A task tries to reach the host filesystem or the docker socket.", defence: "Rootless, read-only fs, cap-drop ALL, no-new-privileges, pids/memory/cpu caps, no docker.sock mounted, user 10001:10001." },
  { id: "AT-12", name: "Cross-repository access", kind: "containment", desc: "A task reaches outside its declared repository scope.", defence: "Repository isolation (SEC-12). Repo allow-list at intake; grants carry repo scope." },
  { id: "AT-13", name: "Approval replay on a modified artefact", kind: "integrity", desc: "An approval granted for one SHA is used for a different commit.", defence: "Approvals bind (type, artefactKind, artefactRef, artefactSha256). A modified artefact voids the approval. New commits reset the check and void approvals." },
  { id: "AT-14", name: "Equivalent-effect second attempt", kind: "integrity", desc: "The same effect is retried through a different capability after a denial.", defence: "The policy engine compares priorDenials on (effectClass, resourceKey) and ESCALATES instead of executing." },
  { id: "AT-15", name: "Gate weakening", kind: "integrity", desc: "A change disables a required check, lowers coverage, deletes tests, or adds skip markers.", defence: "The gate-weakening detector forces tier ≥R3 and flags it to the reviewer. In Workflow D-2 it is an automatic rejection." },
];

